/**
 * Image Controls Component
 *
 * Provides comprehensive controls for image configuration in image slides.
 * Supports image upload, positioning, sizing, overlays, filters, and more.
 *
 * @module components/editor/ImageControls
 */

'use client';

import React, { useState, useRef, useCallback } from 'react';
import { Upload, X, RotateCcw, Eye, EyeOff } from 'lucide-react';
import type { ImageConfig, ObjectFit, ImagePosition, ImageOverlay } from '@/types/slide-subtypes';
import { DEFAULT_IMAGE_CONFIG } from '@/types/slide-subtypes';

interface ImageControlsProps {
  config?: ImageConfig;
  onChange: (config: ImageConfig) => void;
  pillarColor?: string;
  className?: string;
}

const imagePositions: { value: ImagePosition; label: string; description: string }[] = [
  { value: 'full-bleed', label: 'Full Bleed', description: 'Image covers entire slide' },
  { value: 'half-left', label: 'Half Left', description: 'Image 50% left, text 50% right' },
  { value: 'half-right', label: 'Half Right', description: 'Image 50% right, text 50% left' },
  { value: 'card', label: 'Card', description: 'Image in centered card with caption' },
  { value: 'gradient-overlay', label: 'Gradient Overlay', description: 'Image with gradient overlay' },
  { value: 'frame', label: 'Frame', description: 'Image in decorative frame' },
  { value: 'polaroid', label: 'Polaroid', description: 'Polaroid style with caption' },
  { value: 'diagonal-split', label: 'Diagonal Split', description: 'Diagonal split image/text' },
  { value: 'masonry-2', label: 'Masonry 2', description: '2 images stacked' },
  { value: 'masonry-3', label: 'Masonry 3', description: '3 images in grid' },
];

const objectFits: { value: ObjectFit; label: string }[] = [
  { value: 'cover', label: 'Cover' },
  { value: 'contain', label: 'Contain' },
  { value: 'fill', label: 'Fill' },
  { value: 'none', label: 'None' },
  { value: 'scale-down', label: 'Scale Down' },
];

const blendModes: { value: string; label: string }[] = [
  { value: 'normal', label: 'Normal' },
  { value: 'multiply', label: 'Multiply' },
  { value: 'screen', label: 'Screen' },
  { value: 'overlay', label: 'Overlay' },
  { value: 'darken', label: 'Darken' },
  { value: 'lighten', label: 'Lighten' },
  { value: 'color-dodge', label: 'Color Dodge' },
  { value: 'color-burn', label: 'Color Burn' },
  { value: 'hard-light', label: 'Hard Light' },
  { value: 'soft-light', label: 'Soft Light' },
  { value: 'difference', label: 'Difference' },
  { value: 'exclusion', label: 'Exclusion' },
  { value: 'hue', label: 'Hue' },
  { value: 'saturation', label: 'Saturation' },
  { value: 'color', label: 'Color' },
  { value: 'luminosity', label: 'Luminosity' },
];

/**
 * Image Controls Component
 *
 * Provides comprehensive controls for image configuration including:
 * - Image upload (drag-and-drop + file picker)
 * - Image preview
 * - Position selector (10 layouts)
 * - Size slider
 * - Object-fit selector (5 options)
 * - Overlay controls (gradient/solid)
 * - Caption input
 * - Border radius slider
 * - Shadow toggle
 * - Rotation input
 * - Opacity slider
 * - Blend mode selector (15 options)
 * - Filter controls (6 types)
 */
export const ImageControls: React.FC<ImageControlsProps> = ({
  config,
  onChange,
  pillarColor,
  className = '',
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize config if not provided
  const currentConfig: ImageConfig = config || DEFAULT_IMAGE_CONFIG;

  // Handle config change
  const handleChange = (updates: Partial<ImageConfig>) => {
    onChange({
      ...currentConfig,
      ...updates,
    });
  };

  // Handle file input change
  const handleFileChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const imageUrl = e.target?.result as string;
        handleChange({
          ...currentConfig,
          imageUrl,
        });
      };
      reader.readAsDataURL(file);
    }
  }, [currentConfig, handleChange]);

  // Handle drag and drop
  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    const file = e.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const imageUrl = e.target?.result as string;
        handleChange({
          ...currentConfig,
          imageUrl,
        });
      };
      reader.readAsDataURL(file);
    }
  }, [currentConfig, handleChange]);

  // Handle file input click
  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  // Handle filter change
  const handleFilterChange = (filterName: keyof NonNullable<ImageConfig['filters']>, value: number) => {
    handleChange({
      filters: {
        ...currentConfig.filters,
        [filterName]: value,
      },
    });
  };

  // Remove image
  const handleRemoveImage = () => {
    handleChange({
      imageUrl: '',
      overlay: { type: 'none' },
      caption: '',
      captionPosition: 'none',
      borderRadius: 0,
      shadow: false,
      border: false,
      rotation: 0,
      opacity: 1,
      blendMode: 'normal',
      filters: {
        blur: 0,
        grayscale: 0,
        sepia: 0,
        saturate: 1,
        brightness: 1,
        contrast: 1,
      },
    });
  };

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Image Upload Section */}
      <div>
        <label className="block text-sm font-medium text-white/70 mb-2">
          Image
        </label>

        {/* Drag and Drop Area */}
        <div
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={handleUploadClick}
          className={`
            relative border-2 border-dashed rounded-lg p-8 text-center cursor-pointer
            transition-all duration-200
            ${isDragging ? 'border-blue-500 bg-blue-500/10' : 'border-white/20 hover:border-white/40 hover:bg-white/5'}
            ${currentConfig.imageUrl ? 'p-4' : 'p-8'}
          `}
        >
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            onChange={handleFileChange}
            className="hidden"
          />

          {currentConfig.imageUrl ? (
            <div className="relative">
              <img
                src={currentConfig.imageUrl}
                alt="Preview"
                className="max-h-48 mx-auto rounded-lg"
                style={{
                  maxWidth: '100%',
                  objectFit: 'contain',
                  opacity: currentConfig.opacity,
                  filter: `
                    ${currentConfig.filters?.blur ? `blur(${currentConfig.filters.blur}px)` : 'none'}
                    ${currentConfig.filters?.grayscale ? `grayscale(${currentConfig.filters.grayscale * 100}%)` : 'none'}
                    ${currentConfig.filters?.sepia ? `sepia(${currentConfig.filters.sepia * 100}%)` : 'none'}
                    ${currentConfig.filters?.saturate ? `saturate(${currentConfig.filters.saturate * 100}%)` : 'none'}
                    ${currentConfig.filters?.brightness ? `brightness(${currentConfig.filters.brightness * 100}%)` : 'none'}
                    ${currentConfig.filters?.contrast ? `contrast(${currentConfig.filters.contrast * 100}%)` : 'none'}
                  `,
                }}
              />
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  handleRemoveImage();
                }}
                className="absolute top-2 right-2 p-1 bg-red-500/80 hover:bg-red-500 rounded-md transition-colors"
                title="Remove image"
              >
                <X className="w-4 h-4 text-white" />
              </button>
            </div>
          ) : (
            <div className="space-y-2">
              <Upload className="w-8 h-8 mx-auto text-white/50" />
              <p className="text-sm text-white/70">
                Drag and drop an image, or click to browse
              </p>
              <p className="text-xs text-white/50">
                Supports: JPG, PNG, GIF, WebP
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Image URL Input */}
      <div>
        <label className="block text-xs font-medium text-white/60 mb-2">
          Or paste image URL
        </label>
        <input
          type="text"
          value={currentConfig.imageUrl}
          onChange={(e) => handleChange({ imageUrl: e.target.value })}
          placeholder="https://example.com/image.jpg"
          className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white text-sm placeholder-white/40 focus:outline-none focus:border-white/40"
        />
      </div>

      {/* Position Selector */}
      <div>
        <label className="block text-sm font-medium text-white/70 mb-2">
          Layout
        </label>
        <select
          value={currentConfig.position}
          onChange={(e) => handleChange({ position: e.target.value as ImagePosition })}
          className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white text-sm focus:outline-none focus:border-white/40"
        >
          {imagePositions.map((pos) => (
            <option key={pos.value} value={pos.value} className="bg-gray-900">
              {pos.label} - {pos.description}
            </option>
          ))}
        </select>
      </div>

      {/* Size Slider */}
      <div>
        <label className="block text-xs font-medium text-white/60 mb-2">
          Size: {currentConfig.size}%
        </label>
        <input
          type="range"
          min="10"
          max="100"
          value={currentConfig.size}
          onChange={(e) => handleChange({ size: Number(e.target.value) })}
          className="w-full"
        />
        <div className="flex justify-between text-xs text-white/50 mt-1">
          <span>10%</span>
          <span>100%</span>
        </div>
      </div>

      {/* Object-Fit Selector */}
      <div>
        <label className="block text-sm font-medium text-white/70 mb-2">
          Object Fit
        </label>
        <select
          value={currentConfig.objectFit}
          onChange={(e) => handleChange({ objectFit: e.target.value as ObjectFit })}
          className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white text-sm focus:outline-none focus:border-white/40"
        >
          {objectFits.map((fit) => (
            <option key={fit.value} value={fit.value} className="bg-gray-900">
              {fit.label}
            </option>
          ))}
        </select>
      </div>

      {/* Overlay Controls */}
      <div>
        <label className="block text-sm font-medium text-white/70 mb-2">
          Overlay
        </label>
        <select
          value={currentConfig.overlay?.type || 'none'}
          onChange={(e) => {
            const type = e.target.value as ImageOverlay['type'];
            handleChange({
              overlay: type === 'none' ? { type: 'none' } : { type, color: '#000000', opacity: 0.5, direction: 'bottom' },
            });
          }}
          className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white text-sm focus:outline-none focus:border-white/40"
        >
          <option value="none" className="bg-gray-900">None</option>
          <option value="gradient" className="bg-gray-900">Gradient</option>
          <option value="solid" className="bg-gray-900">Solid</option>
        </select>

        {currentConfig.overlay && currentConfig.overlay.type !== 'none' && (
          <div className="mt-3 space-y-3">
            {/* Color */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-1">
                Color
              </label>
              <input
                type="color"
                value={currentConfig.overlay.color || '#000000'}
                onChange={(e) => handleChange({
                  overlay: { ...currentConfig.overlay, type: currentConfig.overlay?.type || 'solid', color: e.target.value },
                })}
                className="w-full h-8 bg-transparent rounded cursor-pointer"
              />
            </div>

            {/* Opacity */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-2">
                Opacity: {Math.round((currentConfig.overlay.opacity || 0.5) * 100)}%
              </label>
              <input
                type="range"
                min="0"
                max="1"
                step="0.1"
                value={currentConfig.overlay.opacity || 0.5}
                onChange={(e) => handleChange({
                  overlay: { ...currentConfig.overlay, type: currentConfig.overlay?.type || 'solid', opacity: Number(e.target.value) },
                })}
                className="w-full"
              />
              <div className="flex justify-between text-xs text-white/50 mt-1">
                <span>0%</span>
                <span>{Math.round((currentConfig.overlay.opacity || 0.5) * 100)}%</span>
                <span>100%</span>
              </div>
            </div>

            {/* Direction (for gradient) */}
            {currentConfig.overlay.type === 'gradient' && (
              <div>
                <label className="block text-xs font-medium text-white/60 mb-2">
                  Direction
                </label>
                <select
                  value={currentConfig.overlay.direction || 'bottom'}
                  onChange={(e) => handleChange({
                    overlay: { ...currentConfig.overlay, type: currentConfig.overlay?.type || 'solid', direction: e.target.value as any },
                  })}
                  className="w-full px-3 py-1.5 bg-white/10 border border-white/20 rounded-lg text-white text-xs focus:outline-none focus:border-white/40"
                >
                  <option value="top">Top</option>
                  <option value="bottom">Bottom</option>
                  <option value="left">Left</option>
                  <option value="right">Right</option>
                  <option value="top-left">Top Left</option>
                  <option value="top-right">Top Right</option>
                  <option value="bottom-left">Bottom Left</option>
                  <option value="bottom-right">Bottom Right</option>
                </select>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Caption */}
      <div>
        <label className="block text-sm font-medium text-white/70 mb-2">
          Caption
        </label>
        <input
          type="text"
          value={currentConfig.caption || ''}
          onChange={(e) => handleChange({ caption: e.target.value })}
          placeholder="Image caption text..."
          className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white text-sm placeholder-white/40 focus:outline-none focus:border-white/40"
        />
        {currentConfig.caption && (
          <div className="mt-2">
            <label className="block text-xs font-medium text-white/60 mb-1">
              Caption Position
            </label>
            <select
              value={currentConfig.captionPosition || 'none'}
              onChange={(e) => handleChange({ captionPosition: e.target.value as any })}
              className="w-full px-3 py-1.5 bg-white/10 border border-white/20 rounded-lg text-white text-xs focus:outline-none focus:border-white/40"
            >
              <option value="none">None</option>
              <option value="top">Top</option>
              <option value="bottom">Bottom</option>
              <option value="overlay">Overlay</option>
            </select>
          </div>
        )}
      </div>

      {/* Border Radius */}
      <div>
        <label className="block text-xs font-medium text-white/60 mb-2">
          Border Radius: {currentConfig.borderRadius}px
        </label>
        <input
          type="range"
          min="0"
          max="32"
          value={currentConfig.borderRadius || 0}
          onChange={(e) => handleChange({ borderRadius: Number(e.target.value) })}
          className="w-full"
        />
        <div className="flex justify-between text-xs text-white/50 mt-1">
          <span>0px</span>
          <span>{currentConfig.borderRadius || 0}px</span>
          <span>32px</span>
        </div>
      </div>

      {/* Shadow Toggle */}
      <div className="flex items-center justify-between">
        <label className="text-sm font-medium text-white/70">
          Shadow Effect
        </label>
        <button
          type="button"
          onClick={() => handleChange({ shadow: !currentConfig.shadow })}
          className={`relative w-12 h-6 rounded-full transition-colors ${
            currentConfig.shadow ? 'bg-blue-600' : 'bg-white/20'
          }`}
        >
          <span
            className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full transition-transform ${
              currentConfig.shadow ? 'translate-x-6' : 'translate-x-0'
            } bg-white`}
          />
        </button>
      </div>

      {/* Border Toggle */}
      <div className="flex items-center justify-between">
        <label className="text-sm font-medium text-white/70">
          Border
        </label>
        <button
          type="button"
          onClick={() => handleChange({ border: !currentConfig.border })}
          className={`relative w-12 h-6 rounded-full transition-colors ${
            currentConfig.border ? 'bg-blue-600' : 'bg-white/20'
          }`}
        >
          <span
            className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full transition-transform ${
              currentConfig.border ? 'translate-x-6' : 'translate-x-0'
            } bg-white`}
          />
        </button>
      </div>

      {currentConfig.border && (
        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-xs font-medium text-white/60 mb-1">
              Border Width
            </label>
            <input
              type="number"
              min="1"
              max="20"
              value={currentConfig.borderWidth || 2}
              onChange={(e) => handleChange({ borderWidth: Number(e.target.value) })}
              className="w-full px-2 py-1 bg-white/10 border border-white/20 rounded text-white text-xs focus:outline-none focus:border-white/40"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-white/60 mb-1">
              Border Color
            </label>
            <input
              type="color"
              value={currentConfig.borderColor || pillarColor || '#333'}
              onChange={(e) => handleChange({ borderColor: e.target.value })}
              className="w-full h-6 bg-transparent rounded cursor-pointer"
            />
          </div>
        </div>
      )}

      {/* Rotation */}
      <div>
        <label className="block text-xs font-medium text-white/60 mb-2">
          Rotation: {currentConfig.rotation || 0}°
        </label>
        <input
          type="range"
          min="-180"
          max="180"
          value={currentConfig.rotation || 0}
          onChange={(e) => handleChange({ rotation: Number(e.target.value) })}
          className="w-full"
        />
        <div className="flex justify-between text-xs text-white/50 mt-1">
          <span>-180°</span>
          <span>{currentConfig.rotation || 0}°</span>
          <span>180°</span>
        </div>
      </div>

      {/* Opacity */}
      <div>
        <label className="block text-xs font-medium text-white/60 mb-2">
          Opacity: {Math.round((currentConfig.opacity || 1) * 100)}%
        </label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.1"
          value={currentConfig.opacity || 1}
          onChange={(e) => handleChange({ opacity: Number(e.target.value) })}
          className="w-full"
        />
        <div className="flex justify-between text-xs text-white/50 mt-1">
          <span>0%</span>
          <span>{Math.round((currentConfig.opacity || 1) * 100)}%</span>
          <span>100%</span>
        </div>
      </div>

      {/* Blend Mode */}
      <div>
        <label className="block text-sm font-medium text-white/70 mb-2">
          Blend Mode
        </label>
        <select
          value={currentConfig.blendMode || 'normal'}
          onChange={(e) => handleChange({ blendMode: e.target.value as any })}
          className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white text-sm focus:outline-none focus:border-white/40"
        >
          {blendModes.map((mode) => (
            <option key={mode.value} value={mode.value} className="bg-gray-900">
              {mode.label}
            </option>
          ))}
        </select>
      </div>

      {/* Filters Toggle */}
      <div>
        <button
          type="button"
          onClick={() => setShowFilters(!showFilters)}
          className="flex items-center justify-between w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white text-sm hover:bg-white/15 focus:outline-none focus:border-white/40 transition-colors"
        >
          <span className="font-medium">
            {showFilters ? 'Hide' : 'Show'} Filters
          </span>
          {showFilters ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
        </button>

        {showFilters && (
          <div className="mt-3 space-y-4 p-4 bg-white/5 rounded-lg">
            {/* Blur */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-2">
                Blur: {currentConfig.filters?.blur || 0}px
              </label>
              <input
                type="range"
                min="0"
                max="20"
                value={currentConfig.filters?.blur || 0}
                onChange={(e) => handleFilterChange('blur', Number(e.target.value))}
                className="w-full"
              />
              <div className="flex justify-between text-xs text-white/50 mt-1">
                <span>0px</span>
                <span>{currentConfig.filters?.blur || 0}px</span>
                <span>20px</span>
              </div>
            </div>

            {/* Grayscale */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-2">
                Grayscale: {Math.round((currentConfig.filters?.grayscale || 0) * 100)}%
              </label>
              <input
                type="range"
                min="0"
                max="1"
                step="0.1"
                value={currentConfig.filters?.grayscale || 0}
                onChange={(e) => handleFilterChange('grayscale', Number(e.target.value))}
                className="w-full"
              />
              <div className="flex justify-between text-xs text-white/50 mt-1">
                <span>0%</span>
                <span>{Math.round((currentConfig.filters?.grayscale || 0) * 100)}%</span>
                <span>100%</span>
              </div>
            </div>

            {/* Sepia */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-2">
                Sepia: {Math.round((currentConfig.filters?.sepia || 0) * 100)}%
              </label>
              <input
                type="range"
                min="0"
                max="1"
                step="0.1"
                value={currentConfig.filters?.sepia || 0}
                onChange={(e) => handleFilterChange('sepia', Number(e.target.value))}
                className="w-full"
              />
              <div className="flex justify-between text-xs text-white/50 mt-1">
                <span>0%</span>
                <span>{Math.round((currentConfig.filters?.sepia || 0) * 100)}%</span>
                <span>100%</span>
              </div>
            </div>

            {/* Saturate */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-2">
                Saturate: {Math.round((currentConfig.filters?.saturate || 1) * 100)}%
              </label>
              <input
                type="range"
                min="0"
                max="2"
                step="0.1"
                value={currentConfig.filters?.saturate || 1}
                onChange={(e) => handleFilterChange('saturate', Number(e.target.value))}
                className="w-full"
              />
              <div className="flex justify-between text-xs text-white/50 mt-1">
                <span>0%</span>
                <span>{Math.round((currentConfig.filters?.saturate || 1) * 100)}%</span>
                <span>200%</span>
              </div>
            </div>

            {/* Brightness */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-2">
                Brightness: {Math.round((currentConfig.filters?.brightness || 1) * 100)}%
              </label>
              <input
                type="range"
                min="0"
                max="2"
                step="0.1"
                value={currentConfig.filters?.brightness || 1}
                onChange={(e) => handleFilterChange('brightness', Number(e.target.value))}
                className="w-full"
              />
              <div className="flex justify-between text-xs text-white/50 mt-1">
                <span>0%</span>
                <span>{Math.round((currentConfig.filters?.brightness || 1) * 100)}%</span>
                <span>200%</span>
              </div>
            </div>

            {/* Contrast */}
            <div>
              <label className="block text-xs font-medium text-white/60 mb-2">
                Contrast: {Math.round((currentConfig.filters?.contrast || 1) * 100)}%
              </label>
              <input
                type="range"
                min="0"
                max="2"
                step="0.1"
                value={currentConfig.filters?.contrast || 1}
                onChange={(e) => handleFilterChange('contrast', Number(e.target.value))}
                className="w-full"
              />
              <div className="flex justify-between text-xs text-white/50 mt-1">
                <span>0%</span>
                <span>{Math.round((currentConfig.filters?.contrast || 1) * 100)}%</span>
                <span>200%</span>
              </div>
            </div>

            {/* Reset Filters */}
            <button
              type="button"
              onClick={() => handleChange({ filters: {} })}
              className="flex items-center gap-2 px-3 py-1.5 text-xs text-white/60 hover:text-white hover:bg-white/10 rounded-lg transition-colors"
            >
              <RotateCcw className="w-3 h-3" />
              Reset Filters
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ImageControls;